-- Requests are negotiation records, NOT payments or completed rentals.
CREATE TABLE IF NOT EXISTS rentall."PedidosAluguer" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "AnuncioId" integer NOT NULL REFERENCES rentall."Anuncios"(id) ON DELETE CASCADE,
  "InteressadoId" text NOT NULL REFERENCES rentall."AspNetUsers"("Id") ON DELETE CASCADE,
  "AnuncianteId" text NOT NULL REFERENCES rentall."AspNetUsers"("Id") ON DELETE CASCADE,
  "Dias" integer NOT NULL CHECK ("Dias" BETWEEN 1 AND 365),
  "PrecoDia" numeric(12,2) NOT NULL CHECK ("PrecoDia" > 0),
  "TotalEstimado" numeric(14,2) NOT NULL CHECK ("TotalEstimado" > 0),
  "ComissaoIndicativa" numeric(14,2) NOT NULL CHECK ("ComissaoIndicativa" >= 0),
  "Estado" varchar(30) NOT NULL DEFAULT 'Pendente'
    CHECK ("Estado" IN ('Pendente','Aceite sem pagamento','Recusado','Cancelado')),
  "CriadoEm" timestamptz NOT NULL DEFAULT now(),
  "RespondidoEm" timestamptz NULL,
  CONSTRAINT "CK_Pedidos_Pessoas" CHECK ("InteressadoId" <> "AnuncianteId")
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Pedidos_Interessado_Pendente"
ON rentall."PedidosAluguer" ("AnuncioId", "InteressadoId")
WHERE "Estado" = 'Pendente';
CREATE INDEX IF NOT EXISTS "IX_Pedidos_Anunciante"
ON rentall."PedidosAluguer" ("AnuncianteId","CriadoEm" DESC);
CREATE INDEX IF NOT EXISTS "IX_Pedidos_Interessado"
ON rentall."PedidosAluguer" ("InteressadoId","CriadoEm" DESC);
REVOKE ALL ON rentall."PedidosAluguer" FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON rentall."PedidosAluguer" TO rentall_app;
GRANT USAGE, SELECT ON SEQUENCE rentall."PedidosAluguer_Id_seq" TO rentall_app;
REVOKE ALL ON SEQUENCE rentall."PedidosAluguer_Id_seq" FROM PUBLIC, anon, authenticated;
